import{_ as l,b as v,c as o,d as a,t as i,C as c,u as p}from"./index-I5uTs6b4.js";const n={class:"level-page"},f={class:"level-content"},r={class:"level-title"},u={__name:"Level25",props:{id:{type:String,required:!0}},setup(d){const s=p();function e(){sessionStorage.setItem("skipIntro","1"),s.push("/")}return(_,t)=>(v(),o("div",n,[a("button",{class:"back-btn",onClick:e},"← Back to Index"),a("div",f,[a("h1",r,"SI-"+i(d.id),1),t[0]||(t[0]=c('<p class="level-name" data-v-d7688a4f>&quot;未知空域&quot;</p><div class="section" data-v-d7688a4f><h2 data-v-d7688a4f>生存难度：Φ</h2><div class="difficulty" data-v-d7688a4f><ul class="class-list" data-v-d7688a4f><li data-v-d7688a4f><span class="class-bullet entity" data-v-d7688a4f></span> 实体数量：不定</li><li data-v-d7688a4f><span class="class-bullet unstable" data-v-d7688a4f></span> 层级稳定性：变化</li></ul></div></div><div class="section" data-v-d7688a4f><h2 data-v-d7688a4f>描述</h2><p data-v-d7688a4f>SI-25 层级是一片大小不定的海上空域，面积不定，大约在 10,000km² 至 250,000km²。其高度限制估测为 30,000m 左右。主要实体只有这片蔚蓝的天空，其余实体皆为实体&quot;天空&quot;所衍生。</p><p data-v-d7688a4f>当流浪者进入其中时，会进入一架在空中稳定飞行的飞机座舱中，飞机型号可能是一战至现代所出现过的飞机型号。飞机中会有一个<strong data-v-d7688a4f>任务板</strong>，上面将有丰富的信息，包括飞机的全套操作手册以及任务目标——目前出现过的&quot;目标&quot;只有击落全部敌机。同时任务板也会告知你是否拥有队友、敌机数量和类型。</p><p data-v-d7688a4f>完成任务后流浪者将获得积分，可用积分换取物资、升级机体、解锁更先进机体（按科技树逐代解锁）。每次任务都有试错机会，若重生次数用完，流浪者将在下一次被击坠时切入 SI-22。</p><p data-v-d7688a4f>在积分达到额定数量时，流浪者可以选择用积分兑换切出，驾驶机体驶向切出点，随后切出至 SI 层群的其他层级的高空，并获得一次性降落伞。</p></div><div class="section appendix" data-v-d7688a4f><h2 data-v-d7688a4f>附录 1：最后的日志</h2><p class="poetic" data-v-d7688a4f>我坐在不断变化的座舱中，磨练着战斗的艺术。<br data-v-d7688a4f>从一无所知，到沧桑的老鸟。<br data-v-d7688a4f>我驾驶古老的钢铁，翻飞银色的蝴蝶；<br data-v-d7688a4f>聆听过活塞的心跳，感受着喷气的轰鸣。<br data-v-d7688a4f>由我击坠的机体足以我离开这片天空。<br data-v-d7688a4f>可我觉得我本就属于这里。<br data-v-d7688a4f>只有这里，这片未知的空域，是我的王国。</p><p class="note" data-v-d7688a4f>*这份残缺日志出现在座舱中，由一位流浪者带回。整本日志仅有这一部分尚未完全烧焦。</p></div><div class="section appendix" data-v-d7688a4f><h2 data-v-d7688a4f>附录 2：无线电记录</h2><p class="log-line" data-v-d7688a4f>他们凭空出现！他们凭空出现！新的实体生成了，准备接敌！</p><p class="log-line" data-v-d7688a4f>他们越来越难缠了！雷达上面一团糟……明明半个月前我们还在用*代机迎敌！</p><p class="log-line" data-v-d7688a4f>为什么这次你也在我的任务目标里，敌我识别里你不是友军！</p></div><div class="section appendix" data-v-d7688a4f><h2 data-v-d7688a4f>附录 3：访谈</h2><p data-v-d7688a4f>&quot;这片天空是活的，是有思维的。从我进去的那一刻我就能感觉得到。它……不不不……祂在观察。它正在试图理解我们，理解我们的思维，理解我们的机械，理解我们的关系……那些该死的实体动作越来越灵巧了，他们学会了我们漫长航空史上一切的一切。我们都是白鼠。&quot;</p></div>',6))])]))}},b=l(u,[["__scopeId","data-v-d7688a4f"]]);export{b as default};
